cy.proyectoPersonal().then((p) => {
  cy.nombreUnico("vyv_limite").then((n) => {
    n8nApi.crearTablaOk(p, n, [{ name: "texto", type: "string" }]).then((t) => {
      const bloque = Array.from({ length: 10 }, () => ({ texto: "x".repeat(5e3) }));
      let rechazada = null;
      const intentar = (i) => {
        if (i > 60 || rechazada) return;
        n8nApi.insertar(p, t.id, bloque).then((r) => {
          if (r.status !== 200) {
            rechazada = { i, r };
            return;
          }
          if (i % 5 === 4) cy.wait(1500);
          intentar(i + 1);
        });
      };
      intentar(0);
      cy.then(() => {
        expect(rechazada, "se esperaba que alguna inserci\xF3n fuera rechazada").to.not.equal(null);
        expect(rechazada.r.status).to.eq(400);
        expect(mensaje(rechazada.r)).to.match(/size limit exceeded/i);
        cy.evidencia(`Rechazo en el bloque ${rechazada.i}: ${mensaje(rechazada.r)}`);
      });
      n8nApi.borrarTabla(p, t.id);
    });
  });
});

n8nApi.subirArchivo("csv/valido.csv", "valido.csv").then((up) => {
  expect(up.status).to.eq(200);
  const meta = up.body.data ?? up.body;
  expect(meta.rowCount).to.eq(5);
  expect(Object.fromEntries(meta.columns.map((c) => [c.name, c.type]))).to.deep.equal({
    nombre: "string",
    edad: "number",
    activo: "boolean",
    fecha: "date"
  });
  cy.evidencia(`Tipos inferidos: ${JSON.stringify(meta.columns.map((c) => `${c.name}:${c.type}`))}`);
  cy.nombreUnico("vyv_csv").then((nombre) => {
    n8nApi.req("POST", n8nApi.dt(p), {
      name: nombre,
      fileId: meta.id,
      hasHeaders: true,
      columns: meta.columns.map((c) => ({ name: c.name, type: c.type, csvColumnName: c.name }))
    }).then((r) => {
      expect(r.status).to.eq(200);
      creadas.push(r.body.data.id);
      n8nApi.filasOk(p, r.body.data.id).should("have.length", 5);
    });
  });
});

